<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3'; import { computed, reactive, ref } from 'vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input';
type Version={id:string;version_number:number;status:string;status_label:string;effective_from:string|null;effective_to:string|null;reference_flour_quantity:string;expected_dough_yield:string;expected_waste_percentage:string;ingredients_count:number;compatible_products_count:number}; type Recipe={id:string;code:string;name:string;description:string|null;is_active:boolean;versions:Version[]}; type Unit={id:string;code:string;name:string}; const props=defineProps<{recipe:Recipe;massUnits:Unit[];today:string;canManage:boolean;canActivate:boolean}>();
const publicationDates=reactive<Record<string,string>>({}); props.recipe.versions.forEach(v=>publicationDates[v.id]=props.today); const selectedVersion=ref(props.recipe.versions.find(v=>v.status==='published')?.id??props.recipe.versions[0]?.id??''); const flourQuantity=ref('1'); const flourUnitId=ref(props.massUnits.find(u=>u.code==='kg')?.id??props.massUnits[0]?.id??''); const scale=ref<any|null>(null); const loading=ref(false); const selected=computed(()=>props.recipe.versions.find(v=>v.id===selectedVersion.value));
const publish=(version:Version)=>router.post(`/recipes/${props.recipe.id}/versions/${version.id}/publish`,{effective_from:publicationDates[version.id]}); const preview=async()=>{if(!selected.value)return;loading.value=true;scale.value=null;const params=new URLSearchParams({flour_quantity:flourQuantity.value,flour_unit_id:flourUnitId.value});const response=await fetch(`/recipes/${props.recipe.id}/versions/${selected.value.id}/scale?${params}`,{headers:{Accept:'application/json'}});scale.value=await response.json();loading.value=false;};
</script>
<template><Head :title="recipe.name" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header class="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><code class="text-xs text-muted-foreground">{{ recipe.code }}</code><h1 class="text-2xl font-semibold">{{ recipe.name }}</h1><p class="text-sm text-muted-foreground">{{ recipe.description }}</p></div><div class="flex gap-2"><Button variant="outline" as-child><Link href="/recipes">Volver</Link></Button><Button v-if="canManage&&!recipe.versions.some(v=>v.status==='draft')" @click="router.post(`/recipes/${recipe.id}/versions`)">Nueva versión</Button></div></header><section class="grid gap-3"><article v-for="version in recipe.versions" :key="version.id" class="rounded-xl border bg-card p-4"><div class="flex flex-col justify-between gap-3 sm:flex-row"><div><div class="flex items-center gap-2"><h2 class="font-semibold">Versión {{ version.version_number }}</h2><span class="rounded-full bg-muted px-2 py-0.5 text-xs">{{ version.status_label }}</span></div><p class="mt-1 text-sm text-muted-foreground">Harina {{ version.reference_flour_quantity }} · rendimiento {{ version.expected_dough_yield }} · merma {{ version.expected_waste_percentage }} %</p><p class="text-xs text-muted-foreground">{{ version.ingredients_count }} ingredientes · {{ version.compatible_products_count }} productos</p><p v-if="version.effective_from" class="mt-1 text-xs">Vigencia: {{ version.effective_from }} a {{ version.effective_to||'indefinida' }}</p></div><div v-if="version.status==='draft'" class="flex flex-wrap items-end gap-2"><Button v-if="canManage" variant="outline" as-child><Link :href="`/recipes/${recipe.id}/versions/${version.id}/edit`">Editar borrador</Link></Button><template v-if="canActivate"><div class="grid gap-1"><span class="text-xs text-muted-foreground">Vigente desde</span><Input v-model="publicationDates[version.id]" type="date" /></div><Button @click="publish(version)">Publicar</Button></template></div></div></article></section><section class="rounded-xl border bg-card p-4"><h2 class="font-semibold">Previsualizar escalado</h2><p class="text-sm text-muted-foreground">Calcula ingredientes y rendimiento para kilos decimales de harina.</p><div class="mt-4 flex flex-wrap items-end gap-3"><div class="grid gap-1"><span class="text-xs">Versión</span><select v-model="selectedVersion" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="version in recipe.versions" :key="version.id" :value="version.id">v{{ version.version_number }} · {{ version.status_label }}</option></select></div><div class="grid gap-1"><span class="text-xs">Harina</span><Input v-model="flourQuantity" class="w-36" type="number" min="0.000001" step="0.000001" /></div><div class="grid gap-1"><span class="text-xs">Unidad</span><select v-model="flourUnitId" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="unit in massUnits" :key="unit.id" :value="unit.id">{{ unit.code }}</option></select></div><Button variant="outline" :disabled="loading" @click="preview">Calcular</Button></div><div v-if="scale" class="mt-5 grid gap-4 lg:grid-cols-2"><div><h3 class="text-sm font-medium">Ingredientes · factor {{ scale.factor }}</h3><div class="mt-2 divide-y rounded-lg border"><div v-for="line in scale.ingredients" :key="line.item" class="flex justify-between px-3 py-2 text-sm"><span>{{ line.item }}</span><strong>{{ line.quantity }} {{ line.unit }}</strong></div></div></div><div><h3 class="text-sm font-medium">Rendimiento {{ scale.expected_dough_yield }} {{ scale.yield_unit }}</h3><div class="mt-2 divide-y rounded-lg border"><div v-for="product in scale.compatible_products" :key="product.presentation_id" class="flex justify-between px-3 py-2 text-sm"><span>{{ product.product }}</span><strong>≈ {{ product.estimated_units }} und</strong></div></div></div></div></section></main></template>
